import { formatAmount, type MemberDetails } from "./entity-details";

export interface EarningsWeek {
  start: string;
  amount: string | null;
  incomplete: boolean;
}

function isEarnings(name: string): boolean {
  const label = name.trim().replace(/\s+/gu, " ").toLowerCase();
  return (
    label === "employment" ||
    label === "employment and earnings" ||
    label === "employment and earnings - ad hoc payments" ||
    label === "employment and earnings - ongoing paid employment"
  );
}

function sum(values: string[]): string | null {
  if (!values.length) return null;
  const scale = Math.max(
    ...values.map((value) => value.split(".")[1]?.length ?? 0),
  );
  const total = values.reduce((total, value) => {
    const [whole, fraction = ""] = value.replace(/^-/, "").split(".");
    const coefficient = BigInt(whole + fraction.padEnd(scale, "0"));
    return total + (value.startsWith("-") ? -coefficient : coefficient);
  }, 0n);
  const digits = (total < 0n ? -total : total)
    .toString()
    .padStart(scale + 1, "0");
  return `${total < 0n ? "-" : ""}${scale ? `${digits.slice(0, -scale)}.${digits.slice(-scale)}` : digits}`;
}

export function formatPounds(amount: string | null): string {
  if (amount === null) return formatAmount(null);
  const unsigned = amount.replace(/^-/, "");
  const [whole, fraction = ""] = unsigned.split(".");
  return `${amount.startsWith("-") ? "−" : ""}£${formatAmount(`${whole}.${fraction.padEnd(2, "0")}`)}`;
}

export function summarizeMember(details: MemberDetails) {
  const pounds = details.summary.currencies.find(
    (group) => group.currency === "GBP",
  );
  const buckets = new Map<string, { amounts: string[]; incomplete: boolean }>();
  let undated = false;
  for (const declaration of details.declarations) {
    if (!isEarnings(declaration.categoryName)) continue;
    const entries = declaration.entries.filter(
      (entry) => entry.currency === "GBP" || !entry.currency?.trim(),
    );
    if (!entries.length) continue;
    if (declaration.registeredAt === null) {
      undated = true;
      continue;
    }
    const date = new Date(declaration.registeredAt);
    date.setUTCHours(0, 0, 0, 0);
    date.setUTCDate(date.getUTCDate() - ((date.getUTCDay() + 6) % 7));
    const start = date.toISOString().slice(0, 10);
    const bucket = buckets.get(start) ?? { amounts: [], incomplete: false };
    for (const entry of entries) {
      if (entry.currency === "GBP" && entry.amount !== null)
        bucket.amounts.push(entry.amount);
      else bucket.incomplete = true;
    }
    buckets.set(start, bucket);
  }
  const dates = [...buckets.keys()].sort();
  const first = dates[0];
  const last = dates.at(-1);
  const earnings: EarningsWeek[] = [];
  if (first !== undefined && last !== undefined) {
    const date = new Date(`${first}T00:00:00Z`);
    for (
      let start = first;
      start <= last;
      start = date.toISOString().slice(0, 10)
    ) {
      const bucket = buckets.get(start);
      earnings.push({
        start,
        amount: bucket ? sum(bucket.amounts) : "0",
        incomplete: bucket?.incomplete ?? false,
      });
      date.setUTCDate(date.getUTCDate() + 7);
    }
  }
  return {
    total: pounds?.amount ?? null,
    categories: pounds?.categories ?? [],
    earnings,
    undated,
  };
}
<script lang="ts">
  import { categoryBars, registrationDate } from "./lib/entity-details";
  import { formatPounds, type EarningsWeek } from "./lib/member-summary";
  let { weeks, undated }: { weeks: EarningsWeek[]; undated: boolean } =
    $props();
  const bars = $derived(categoryBars(weeks));
  const positive = $derived(
    Math.max(0, ...bars.filter((bar) => !bar.negative).map((bar) => bar.width)),
  );
  const negative = $derived(
    Math.max(0, ...bars.filter((bar) => bar.negative).map((bar) => bar.width)),
  );
  const extent = $derived(positive + negative || 100);
  const baseline = $derived(24 + (positive / extent) * 184);
  const maximum = $derived(
    weeks[bars.findIndex((bar) => !bar.negative && bar.width === positive)]
      ?.amount ?? "0",
  );
  const minimum = $derived(
    weeks[bars.findIndex((bar) => bar.negative && bar.width === negative)]
      ?.amount ?? "0",
  );
  function tick(index: number): boolean {
    return (
      index === 0 ||
      index === weeks.length - 1 ||
      (weeks.length > 10 && index % Math.ceil(weeks.length / 4) === 0)
    );
  }
  function month(start: string): string {
    return new Intl.DateTimeFormat("en-GB", {
      month: "short",
      year: "numeric",
      timeZone: "UTC",
    }).format(new Date(start));
  }
</script>

<section class="member-earnings" aria-labelledby="earnings-heading">
  <h2 id="earnings-heading">Earnings per week</h2>
  <p class="chart-subtitle">By registration week</p>
  {#if weeks.length}
    <svg
      class="earnings-chart"
      viewBox="0 0 560 250"
      role="img"
      aria-labelledby="earnings-title earnings-description"
    >
      <title id="earnings-title">Weekly registered earnings</title><desc
        id="earnings-description"
        >Pound amounts by Monday registration week. Exact amounts are available
        in the weekly earnings table below.</desc
      >
      <text x="0" y="16" class="chart-axis">{formatPounds(maximum)}</text><line
        x1="0"
        x2="560"
        y1={baseline}
        y2={baseline}
        class="chart-baseline"
      />
      {#each weeks as week, index}{@const bar = bars[index]}{@const height =
          (bar.width / extent) * 184}
        <rect
          x={(index * 560) / weeks.length + 1}
          y={bar.negative ? baseline : baseline - height}
          width={Math.max(1, 560 / weeks.length - 2)}
          {height}
          class="earnings-bar"
          class:negative={bar.negative}
          ><title
            >Week of {registrationDate(week.start)}: {formatPounds(
              week.amount,
            )}{week.incomplete ? " (some amounts unavailable)" : ""}</title
          ></rect
        >
        {#if tick(index)}<text
            x={(index * 540) / Math.max(1, weeks.length - 1) + 10}
            y="244"
            text-anchor={index === 0
              ? "start"
              : index === weeks.length - 1
                ? "end"
                : "middle"}
            class="chart-axis">{month(week.start)}</text
          >{/if}{/each}
      <text
        x="0"
        y={negative ? 225 : Math.min(225, baseline + 16)}
        class="chart-axis">{negative ? formatPounds(minimum) : "£0"}</text
      >
    </svg>
    {#if weeks.some((week) => week.incomplete)}<p class="partial-note">
        Some weekly amounts are unavailable.
      </p>{/if}
    <details class="earnings-values">
      <summary>View weekly amounts</summary>
      <table>
        <caption class="visually-hidden">Weekly registered earnings</caption
        ><thead
          ><tr
            ><th scope="col">Week starting</th><th scope="col"
              >Declared earnings</th
            ></tr
          ></thead
        ><tbody
          >{#each weeks as week}<tr
              ><th scope="row"
                ><time datetime={week.start}
                  >{registrationDate(week.start)}</time
                ></th
              ><td
                >{formatPounds(week.amount)}{#if week.incomplete}<span
                    class="partial-note">Some amounts unavailable</span
                  >{/if}</td
              ></tr
            >{/each}</tbody
        >
      </table>
    </details>
  {:else}<p class="empty-details">
      {undated
        ? "Registration dates are unavailable for earnings."
        : "No registered earnings available."}
    </p>{/if}
  {#if undated && weeks.length}<p class="partial-note">
      Earnings without registration dates are excluded.
    </p>{/if}
</section>
